import importlib.metadata as m, sys
def version(name):
    try:
        return m.version(name)
    except m.PackageNotFoundError:
        return None
print(repr({'python': sys.version, 'executable': sys.executable, 'fastapi': version('fastapi'), 'fastapi-cli': version('fastapi-cli'),
            'starlette': version('starlette'), 'uvicorn': version('uvicorn'), 'pydantic': version('pydantic'), 'packages': len(list(m.distributions()))}))
